exercise.solution:
CREATE TABLE lab_l11_magazines (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL CHECK (length(trim(title)) > 0),
  publisher_id INTEGER NOT NULL CHECK (publisher_id > 0)
);

